def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True
思路：1 和 0 非质数；2、3 是；偶数或 3 的倍数直接排除；其余只需检查形如 6k±1 的因子且到平方根即可，复杂度 O(sqrt(n))，比逐个整除快得多。

def reverse_str(s):
    result = []
    for i in range(len(s) - 1, -1, -1):
        result.append(s[i])
    return ''.join(result)
时间复杂度 O(n)、空间复杂度 O(n)。逐字符反向收集到列表再拼接，避免字符串不可变导致的 O(n²) 拼接开销。

def quicksort(a):
    if len(a) <= 1:
        return a
    pivot = a[len(a) // 2]
    left = [x for x in a if x < pivot]
    mid = [x for x in a if x == pivot]
    right = [x for x in a if x > pivot]
    return quicksort(left) + mid + quicksort(right)
平均时间复杂度 O(n log n)，最坏（已排序且枢轴选得差）O(n²)，空间平均 O(log n)。此处取中位元素为枢轴，能规避常见的已排序退化。

def binary_search(arr, target):
    lo, hi = 0, len(arr) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1
每次排除一半，前提是数组已升序，复杂度 O(log n)。边界用 lo<=hi，目标在左右淘汰中收敛。

def count_lines(in_path, out_path):
    with open(in_path, encoding='utf-8') as f, open(out_path, 'w', encoding='utf-8') as g:
        for line in f:
            g.write(f"{len(line)}")
这样逐行处理，内存占用与文件大小无关。要点：用 with 保证资源释放，指定 encoding 避免中文乱码。

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a
用欧几里得算法：gcd(a,b) = gcd(b, a mod b)，直到 b 为 0。复杂度 O(log min(a,b))，比逐数试除快得多。

def merge(a, b):
    res, i, j = [], 0, 0
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            res.append(a[i]); i += 1
        else:
            res.append(b[j]); j += 1
    res.extend(a[i:])
    res.extend(b[j:])
    return res
双指针归并：每次取两指针较小的，剩余部分一次性接上，O(m+n)。这就是归并排序的合并步骤。

import time, functools
def timed(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        try:
            return func(*args, **kwargs)
        finally:
            cost = (time.perf_counter() - start) * 1000
            print(f"{func.__name__} 耗时 {cost:.3f} ms")
    return wrapper
用 perf_counter（精度高）、finally 保证即使报错也计时、wraps 保留原函数元数据。

def fib(n):
    a, b = 0, 1
    for _ in range(n):
        yield a
        a, b = b, a + b
for x in fib(8):
    print(x)  # 0 1 1 2 3 5 8 13
生成器用 yield 惰性求值，不一次性在内存里建整个列表，适合大 n。状态在 a,b 之间滚动推进。

def word_count(text):
    from collections import Counter
    return dict(Counter(text.split()))
text.split() 按空白切词，Counter 直接在内部构建频次字典。若需忽略大小写可先 .lower()。复杂度 O(n)。

class Singleton:
    _instance = None
    def __new__(cls, *args, **kwargs):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
        return cls._instance
适用：配置管理器、日志、线程池等全局唯一对象。注意 Python 中多线程下需加锁保证线程安全；也可用模块级变量方案规避。
